interface DraggableProps {
  children: React.ReactNode;
}

function Draggable({ children }: DraggableProps): React.JSX.Element {
  const [offset, setOffset] = useState<{ x: number; y: number }>({
    x: 0,
    y: 0,
  });
  const [dragging, setDragging] = useState<boolean>(false);
  const start = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const origin = useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    setDragging(true);
    start.current = { x: e.clientX, y: e.clientY };
    origin.current = offset;
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    const dx = e.clientX - start.current.x;
    const dy = e.clientY - start.current.y;
    setOffset({ x: origin.current.x + dx, y: origin.current.y + dy });
  };

  const releaseAndSpringBack = () => {
    if (!dragging) return;
    setDragging(false);
    setOffset({ x: 0, y: 0 });
  };

  return (
    <div
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={releaseAndSpringBack}
      onPointerLeave={releaseAndSpringBack}
      onPointerCancel={releaseAndSpringBack}
      style={{
        transform: `translate(${offset.x}px, ${offset.y}px) scale(${dragging ? 1.08 : 1})`,
        transition: dragging
          ? "transform 0.05s linear"
          : "transform 0.7s cubic-bezier(0.34, 1.56, 0.64, 1)",
        cursor: dragging ? "grabbing" : "grab",
        touchAction: "none",
        zIndex: dragging ? 50 : 1,
        position: "relative",
      }}
    >
      {children}
    </div>
  );
}

/* ---------- photo card (rounded, soft-shadow frame around a real photo) ---------- */
interface PhotoCardProps {
  src: string;
  alt: string;
  size?: number;
  rotate?: number;
}

function PhotoCard({
  src,
  alt,
  size = 130,
  rotate = 0,
}: PhotoCardProps): React.JSX.Element {
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "34% 66% 62% 38% / 40% 36% 64% 60%",
        overflow: "hidden",
        border: `4px solid ${COLORS.cream}`,
        outline: "2px solid rgba(43,30,26,0.12)",
        boxShadow: "0 16px 28px rgba(43,30,26,0.18)",
        transform: `rotate(${rotate}deg)`,
        background: COLORS.cream,
      }}
    >
      <img
        src={src}
        alt={alt}
        draggable={false}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          display: "block",
          pointerEvents: "none",
        }}
      />
    </div>
  );
}

/* ---------- floating wrapper (idle bob animation for position) ---------- */
interface FloatProps {
  children: React.ReactNode;
  delay?: number;
  duration?: number;
  x?: string | number;
  y?: string | number;
  className?: string;
}

function Float({
  children,
  delay = 0,
  duration = 6,
  x = 0,
  y = 0,
  className = "",
}: FloatProps): React.JSX.Element {
  return (
    <div
      className={`absolute ${className}`}
      style={{
        left: x,
        top: y,
        animation: `bob ${duration}s ease-in-out infinite`,
        animationDelay: `${delay}s`,
      }}
    >
      {children}
    </div>
  );
}

function SteamWisp({
  delay = 0,
  left = 0,
}: {
  delay?: number;
  left?: number;
}): React.JSX.Element {
  return (
    <svg
      width="18"
      height="46"
      viewBox="0 0 18 46"
      fill="none"
      style={{
        position: "absolute",
        left,
        bottom: 0,
        animation: `steamRise 3.4s ease-in-out infinite`,
        animationDelay: `${delay}s`,
        opacity: 0,
      }}
    >
      <path
        d="M9 44c5-6-5-10 0-18S4 12 9 2"
        stroke={COLORS.wineLight}
        strokeWidth="2.6"
        strokeLinecap="round"
        fill="none"
        opacity="0.55"
      />
    </svg>
  );
}

